create or replace function pg_temp.wid(text) returns uuid language sql immutable as $$ select md5('waysocial:' || $1)::uuid $$;

-- usuários de demonstração
values ('00000000-0000-0000-0000-000000000000', pg_temp.wid('u_lucas'), 'authenticated', 'authenticated', 'lucas@waysocial.demo', extensions.crypt('waysocial', extensions.gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}'::jsonb, '{"username":"lucas.viaja","display_name":"Lucas Andrade"}'::jsonb, now(), now(), '', '', '', '');
